    let mut schema_c: u32 = 0;
    // word 0, 32 bits: f085_bits[0..21], f086_uint[0..9], f087_f64[0..2]
    schema_stream.serialize_bits(&mut schema_c, 32)?;
    let schema_c0 = u64::from(schema_c);
    // word 1, 32 bits: f087_f64[2..34]
